import numpy as np
from scipy.optimize import brentq
def u(v):
    v=np.asarray(v,float); return v/np.linalg.norm(v)
def tetra_remaining(b1,b2):
    b1=u(b1); b2=u(b2); m=u(b1+b2); n=u(np.cross(b1,b2)); a=np.deg2rad(54.735)
    return -np.cos(a)*m+np.sin(a)*n, -np.cos(a)*m-np.sin(a)*n

R=1.199; CpTi=2.08; half=np.deg2rad(65.)
def geom(phi0_deg):
    atoms=[]
    def add(e,p): atoms.append([e,np.asarray(p,float)]); return len(atoms)-1
    def methyl(cpos,dirout,rCH=1.09):
        d=u(dirout); t=np.array([1.,0.,0.])
        if abs(np.dot(t,d))>0.9: t=np.array([0.,1.,0.])
        p1=u(np.cross(d,t)); p2=np.cross(d,p1); ang=np.deg2rad(109.5)
        P=np.array([a[1] for a in atoms]); best=None
        for ph in np.deg2rad(np.arange(0,120,4)):
            hs=np.array([cpos+rCH*u(np.cos(np.pi-ang)*d+np.sin(np.pi-ang)*(np.cos(ph+2*np.pi*k/3)*p1+np.sin(ph+2*np.pi*k/3)*p2)) for k in range(3)])
            md=np.linalg.norm(hs[:,None]-P[None],axis=-1).min()
            if best is None or md>best[0]: best=(md,hs)
        return best[1]
    phi0=np.deg2rad(phi0_deg)
    add('Ti',[0,0,0]); cme=np.array([2.10,0,0]); add('C',cme)
    for h in methyl(cme,[1,0,0]): add('H',h)
    info={}
    for s in (+1,-1):
        n1=np.array([-np.cos(half),0,s*np.sin(half)]); cen=CpTi*n1
        ea=np.array([0.,s*1.,0.])
        eb=u(np.cross(n1,np.array([0.,1.,0.]))) if s==1 else u(np.cross(np.array([0.,1.,0.]),n1))
        if eb[0]>0: eb=-eb
        ring=[cen+R*(np.cos(phi0+np.deg2rad(72*k))*eb+np.sin(phi0+np.deg2rad(72*k))*ea) for k in range(5)]
        info[s]=(ring,cen,n1)
    # Si positions + solve bridge
    si={}; 
    for s in (+1,-1):
        ring,cen,n1=info[s]
        si[s]=ring[0]+1.87*u(ring[0]-cen)
    # cone at Si1
    d_ip=u(info[1][0][0]-si[1])   # Si->Cip
    # basis perpendicular
    t=np.array([0.,0.,1.]); 
    p1=u(np.cross(d_ip,t)); p2=np.cross(d_ip,p1)
    ang=np.deg2rad(109.5)
    def Ca(tt):
        d=np.cos(ang)*d_ip+np.sin(ang)*(np.cos(tt)*p1+np.sin(tt)*p2)
        return si[1]+1.87*u(d)
    def f(tt):
        ca=Ca(tt); cb=np.array([ca[0],-ca[1],-ca[2]])
        return np.linalg.norm(ca-cb)-1.545
    ts=np.linspace(0,2*np.pi,721); vals=[f(t_) for t_ in ts]
    roots=[]
    for i in range(720):
        if vals[i]*vals[i+1]<0: roots.append(brentq(f,ts[i],ts[i+1]))
    # pick root giving ca most toward -x (away from Ti) and with reasonable Si-C-C angle
    best=None
    for r in roots:
        ca=Ca(r); cb=np.array([ca[0],-ca[1],-ca[2]])
        a=np.degrees(np.arccos(u(si[1]-ca).dot(u(cb-ca))))
        sc=-ca[0]+0.0*a
        if a<95: continue
        if best is None or sc>best[0]: best=(sc,r,ca,cb,a)
    if best is None: return None
    _,r,ca,cb,a=best
    # now build full
    for s in (+1,-1):
