    for (c,sp,other) in ((ca,si[1],cb),(cb,si[-1],ca)):
        for d in tetra_remaining(sp-c,other-c): add('H',c+1.10*d)
    for s,cbr in ((1,ca),(-1,cb)):
        for d in tetra_remaining(info[s][0][0]-si[s],cbr-si[s]):
            cm=si[s]+1.87*d; add('C',cm)
            for h in methyl(cm,d): add('H',h)
    P=np.array([x[1] for x in atoms]); E=[x[0] for x in atoms]
    D=np.linalg.norm(P[:,None]-P[None],axis=-1)+np.eye(len(P))*9
    return atoms,D.min(),a,np.linalg.norm(si[1]-si[-1])

