def u(v): 
    v=np.asarray(v,float); return v/np.linalg.norm(v)
def methyl(ci,pi,rCH=1.09):
    c=atoms[ci][1]; d=u(c-atoms[pi][1])
    t=np.array([1.,0.,0.])
    if abs(d.dot(t))>0.9: t=np.array([0.,1.,0.])
    p1=u(np.cross(d,t)); p2=np.cross(d,p1); ang=np.deg2rad(110.5)
    Q=np.array([a[1] for a in atoms]); best=None
    for ph in np.deg2rad(np.arange(0,120,2)):
        hs=np.array([c+rCH*u(np.cos(np.pi-ang)*d+np.sin(np.pi-ang)*(np.cos(ph+2*np.pi*k/3)*p1+np.sin(ph+2*np.pi*k/3)*p2)) for k in range(3)])
        D=np.linalg.norm(hs[:,None]-Q[None],axis=-1)
        md=np.sort(D.ravel())[3:].min()  # exclude self C distances
        if best is None or md>best[0]: best=(md,hs)
    for h in best[1]: atoms.append(['H',h])
